// Validates one appointment typed in the form and prepares the row. Nothing is saved when anything is wrong:
// the person who typed it is told why (the form shows the message). Free text that is echoed into WhatsApp
// is cleaned (control characters), capped (max_text_length) and refused when it carries a web address or an @mention.
const s = $('Your settings').first().json;
const recent = $input.all().map((item) => item.json).filter((row) => row.id !== undefined);
const refuse = (reason) => [{ json: { ok: false, message: 'Not saved. ' + reason + ' Nothing was saved, please correct the entry and submit it again.' } }];

if ($now.zoneName !== s.expected_timezone) {
	return refuse('This form is not set up yet: the workflow time zone is ' + $now.zoneName + ' but expected_timezone in Your settings is ' + s.expected_timezone + '. Ask the owner to fix it.');
}
const dayAgo = Date.now() - 24 * 3600000;
if (recent.filter((row) => Date.parse(row.createdAt) >= dayAgo).length >= Number(s.max_appointments_per_day)) {
	return refuse('The limit of ' + s.max_appointments_per_day + ' new appointments in 24 hours is reached.');
}

const max = Number(s.max_text_length) > 0 ? Number(s.max_text_length) : 100;
// Control characters, zero-width and bidirectional marks become spaces (written as escapes on purpose).
const clean = (value) => String(value ?? '').replace(/[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2066-\u2069]/g, ' ').replace(/\s+/g, ' ').trim();
const hasLink = (text) => /https?:|www\.|@\d/i.test(text);
const name = clean(s['Customer name']);
const title = clean(s['Appointment']);
const location = clean(s['Location']);
const notes = clean(s['Notes']);
const date = clean(s['Date']);
const time = clean(s['Time']);
const errors = [];
if (!name) errors.push('The customer name is empty.');
if (!title) errors.push('The appointment title is empty.');
for (const [label, value] of [['customer name', name], ['appointment title', title], ['location', location], ['notes', notes]]) {
	if (value.length > max) errors.push('The ' + label + (label === 'notes' ? ' are' : ' is') + ' longer than ' + max + ' characters.');
}
for (const [label, value] of [['customer name', name], ['appointment title', title], ['location', location]]) {
	if (hasLink(value)) errors.push('The ' + label + ' cannot contain a web address or an @mention.');
}

// Phone: E.164 only where it is unambiguous. Local formats get default_country_code only for 55 (Brazil: the area
// code and the 9 digit mobile number are needed). With another code, only numbers that start with that code or
// with + are accepted: a leading 0 or a trunk prefix cannot be told apart from the number itself, so it is not guessed.
const country = String(s.default_country_code || '55').replace(/\D/g, '');
const international = (digits) => {
	if (!/^[1-9]\d{7,14}$/.test(digits)) return { error: 'The WhatsApp number is not a valid international number.' };
	if (digits.startsWith('55') && !(digits.length === 13 && digits[4] === '9')) {
		return { error: 'A Brazilian mobile number has the country code 55, the area code, then 9 and 8 more digits.' };
	}
	return { phone: '+' + digits };
};
const toE164 = (raw) => {
	const cleaned = String(raw ?? '').trim().replace(/[\s().-]/g, '');
	if (!/^\+?\d+$/.test(cleaned)) return { error: 'The WhatsApp number must be digits with the area code, for example +55XXXXXXXXXXX (the country code, the area code, then the number).' };
	if (cleaned.startsWith('+')) return international(cleaned.slice(1));
	if (cleaned.startsWith('00')) return international(cleaned.slice(2));
	let digits = cleaned;
	if (country === '55') {
		digits = digits.replace(/^0(?=\d{10,11}$)/, '');
		if (/^55\d{11}$/.test(digits)) return international(digits);
		if (/^[1-9][1-9]9\d{8}$/.test(digits)) return international('55' + digits);
		if (/^(55)?[1-9][1-9]\d{8}$/.test(digits)) return { error: 'The WhatsApp number looks like it lacks the ninth digit: add the 9 after the area code.' };
		return { error: 'The WhatsApp number needs the area code and the 9 digit mobile number, or must start with + and the country code.' };
	}
	if (digits.startsWith(country)) return international(digits);
	return { error: 'The WhatsApp number must start with + and the country code.' };
};
const parsed = toE164(s['WhatsApp number']);
if (parsed.error) errors.push(parsed.error);

// The date and time are read in the time zone of this workflow (checked above) and stored in UTC.
const timeOk = /^([01]?\d|2[0-3]):[0-5]\d$/.test(time);
const start = DateTime.fromFormat(date + ' ' + (timeOk ? time.padStart(5, '0') : ''), 'yyyy-MM-dd HH:mm', { zone: $now.zoneName });
if (!timeOk) errors.push('The time must look like 14:30.');
else if (!start.isValid) errors.push('The date is not valid.');
else if (start.toMillis() <= Date.now()) errors.push('The appointment is not in the future.');
const asked = Number(s['Duration in minutes']);
if (asked > 1440) errors.push('The duration is longer than 1440 minutes.');
if (errors.length) return refuse(errors.join(' '));

const first = DateTime.fromMillis(start.toMillis(), { zone: $now.zoneName }).toFormat('ccc d LLL HH:mm');
// The same phone at the same start, saved in the last 24 hours, is the form sent twice: refuse it instead of inviting twice.
if (recent.some((row) => row.phone === parsed.phone && Date.parse(row.start_at) === start.toMillis())) {
	return refuse('An appointment for ' + parsed.phone + ' on ' + first + ' is already in the table.');
}

const minutes = asked > 0 ? Math.round(asked) : Number(s.default_duration_minutes);
const soon = start.toMillis() - Date.now() < Number(s.min_notice_minutes) * 60000;
const reminderNote = soon
	? 'It starts in less than ' + s.min_notice_minutes + ' minutes, so no reminder will be sent.'
	: 'The customer is reminded by the first hourly run that falls within ' + s.reminder_hours_before + ' hours of the start.';
return [{
	json: {
		ok: true,
		message: 'Saved: ' + name + ', ' + parsed.phone + ', ' + title + ', ' + first + ' (' + $now.zoneName + '). ' + reminderNote,
		customer_name: name,
		phone: parsed.phone,
		title,
		location: location || String(s.business_location ?? ''),
		start_at: start.toUTC().toISO(),
		duration_min: minutes,
		status: 'scheduled',
		reminder_message_id: '',
		reminded_at: '',
		rsvp_at: '',
		extra_guests: 0,
		last_error: '',
		notes,
	},
}];

const s = $('Your settings').first().json;
if (!/^\+[1-9]\d{7,14}$/.test(String(s.owner_phone ?? ''))) {
	throw new Error('Your settings: set owner_phone to your own WhatsApp number, with + and the country code, for example +55XXXXXXXXXXX (the country code, the area code, then the number).');
}
if ($now.zoneName !== s.expected_timezone) {
	throw new Error('Time zone mismatch: this workflow runs in ' + $now.zoneName + ' but expected_timezone in Your settings is ' + s.expected_timezone + '. Set the time zone in the workflow settings, or change expected_timezone, so that the times you type are the times customers read.');
}

// Plans the invitations of this run. The rows were read with their window already applied: they start between
// min_notice_minutes and reminder_hours_before from now, earliest first. One message of the quota always stays free
// for the message to the owner: rows that do not fit are not sent now and are listed for the owner afterwards.
if (!String(s.invite_text ?? '').trim()) throw new Error('Your settings: invite_text is empty.');
// Texts come from Your settings. {name}, {business}, {when}, {where}; \n is a line break; a line with {where} is dropped without a location.
const fill = (template, values) => String(template).replace(/\\n/g, '\n').split('\n')
	.filter((line) => values.where || !line.includes('{where}'))
	.map((line) => line.replace(/\{(\w+)\}/g, (all, key) => (key in values ? values[key] : all)))
	.join('\n').trim();
const quota = $('Get the message quota').first().json;
const room = typeof quota.remaining === 'number' ? Math.max(0, quota.remaining - 1) : Infinity;
const e164 = /^\+[1-9]\d{7,14}$/;
const rows = $input.all().map((item) => item.json)
	.filter((row) => row.id !== undefined && Number.isFinite(Date.parse(row.start_at)))
	.sort((a, b) => Date.parse(a.start_at) - Date.parse(b.start_at))
	.slice(0, room);
return rows.map((r) => {
	const start = Date.parse(r.start_at);
	const minutes = Number(r.duration_min) > 0 ? Number(r.duration_min) : Number(s.default_duration_minutes);
	const when = DateTime.fromMillis(start, { zone: $now.zoneName }).toFormat(String(s.date_format || "cccc d LLLL 'at' HH:mm"));
	const first = String(r.customer_name || '').trim().split(/\s+/)[0] || 'there';
	const where = String(r.location || '').trim();
	return {
		json: {
			...r,
			phone_ok: e164.test(String(r.phone || '')),
			idempotency_key: 'appt-' + r.id + '-' + start,
			event_name: (r.title + ' at ' + s.business_name).slice(0, 200),
			// Guests on a personal WhatsApp account see the invitation without the time card: the text repeats it.
			event_description: fill(s.invite_text, { name: first, business: s.business_name, when, where }),
			start_iso: new Date(start).toISOString(),
			end_iso: new Date(start + minutes * 60000).toISOString(),
			alarm_minutes: Number(s.invite_alarm_minutes_before),
			allow_extra_guests: s.allow_extra_guests === true,
		},
	};
});

// ONE message to the owner for this run, listing only exceptions: reminders that were not sent (with the reason),
// sends that failed, customers who have not answered, and the quota left when it was the cause. Nothing to report: no message.
const s = $('Your settings').first().json;
const zone = $now.zoneName;
const hash = (text) => { let h = 5381; for (const c of text) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(16); };
const rowsOf = (name) => ($(name).isExecuted ? $(name).all() : []).map((item) => item.json).filter((row) => row.id !== undefined);
const now = Date.now();
const when = (r) => DateTime.fromISO(r.start_at).setZone(zone).toFormat('ccc d LLL HH:mm');
const who = (r) => r.customer_name + ', ' + r.title + ', ' + when(r);

const readIds = new Set(rowsOf('Read the appointments to remind').map((r) => r.id));
const attempted = rowsOf('Record the reminder or the failure');
const sentCount = attempted.filter((r) => r.status === 'reminded').length;
const failed = attempted.filter((r) => r.status === 'send_failed' || r.status === 'invalid_phone');
const notSent = rowsOf('Flag reminders that were not sent');
const silent = $input.all().map((item) => item.json).filter((row) => row.id !== undefined);

let quotaBlocked = 0;
const why = (r) => {
	const start = Date.parse(r.start_at);
	if (!Number.isFinite(start)) return 'the start time is missing or not a valid date';
	if (start <= now) return 'the appointment had already started when the run saw it (added too late, or n8n was not running)';
	if (start - now < Number(s.min_notice_minutes) * 60000) {
		return 'it starts in ' + Math.max(1, Math.round((start - now) / 60000)) + ' minutes, less than the ' + s.min_notice_minutes + ' minutes of notice a reminder needs';
	}
	if (readIds.has(r.id)) { quotaBlocked += 1; return 'the message quota had no room for it'; }
	return 'it was added while this run was working';
};

const parts = [];
if (notSent.length) parts.push('Not reminded (' + notSent.length + '):\n' + notSent.map((r) => '- ' + who(r) + ': ' + why(r)).join('\n'));
if (failed.length) {
	parts.push('Reminder failed (' + failed.length + '):\n' + failed.map((r) => '- ' + who(r) + ': ' + (r.status === 'invalid_phone' ? 'the phone number is not valid (' + r.phone + ')' : r.last_error)).join('\n'));
}
if (silent.length) {
	parts.push('No answer yet (' + silent.length + '):\n' + silent.map((r) => '- ' + who(r) + ', ' + r.phone + ', in ' + (Math.round((Date.parse(r.start_at) - now) / 360000) / 10) + ' h').join('\n'));
}
if (quotaBlocked > 0) {
	const q = $('Get the message quota').first().json;
	const left = typeof q.remaining === 'number' ? Math.max(0, q.remaining - sentCount - 1) : 'unknown';
	const resets = q.resets_at ? DateTime.fromISO(q.resets_at).setZone(zone).toFormat('d LLL') : '';
	parts.push('Message quota left: ' + left + (q.quota ? ' of ' + q.quota : '') + ' (one message is always kept for this report)' + (resets ? ', it resets on ' + resets : '') + '.');
}
if (!parts.length) return [];
let text = 'Appointment reminders, ' + s.business_name + ' (' + DateTime.now().setZone(zone).toFormat('ccc d LLL HH:mm') + ', ' + zone + '):\n\n' + parts.join('\n\n');
if (notSent.length || failed.length) text += '\n\nTo try a row again, fix the cause and set its status back to scheduled in the appointments table.';
if (text.length > 3800) text = text.slice(0, 3800) + '\n...and more in the appointments table.';
return [{ json: { phone: s.owner_phone, text, key: 'report-' + DateTime.now().setZone(zone).toFormat('yyyy-MM-dd-HH') + '-' + hash(text) } }];

const s = $('Your settings').first().json;
if (!/^\+[1-9]\d{7,14}$/.test(String(s.owner_phone ?? ''))) {
	throw new Error('Your settings: set owner_phone to your own WhatsApp number, with + and the country code, for example +55XXXXXXXXXXX (the country code, the area code, then the number).');
}
if ($now.zoneName !== s.expected_timezone) {
	throw new Error('Time zone mismatch: this workflow runs in ' + $now.zoneName + ' but expected_timezone in Your settings is ' + s.expected_timezone + '. Set the time zone in the workflow settings, or change expected_timezone, so that the times you type are the times customers read.');
}

// The texts the customer reads are in Your settings (thanks_going_text, thanks_maybe_text, decline_customer_text).
// {name} is the first name; {title}, {business}, {when} come from the row and the settings; {guests} is the extra guests sentence.
const fill = (template, values) => String(template).replace(/\\n/g, '\n').replace(/\{(\w+)\}/g, (all, key) => (key in values ? values[key] : all)).trim();
const customerText = { confirmed: s.thanks_going_text, tentative: s.thanks_maybe_text, declined: s.decline_customer_text };
for (const [status, text] of Object.entries(customerText)) {
	if (!String(text ?? '').trim()) throw new Error('Your settings: the text for ' + status + ' answers is empty (thanks_going_text, thanks_maybe_text or decline_customer_text).');
}
// The texts to you (the owner) are written here.
const plain = (text) => String(text).replace(/[.\s]+$/, '');
const wording = {
	ownerDeclined: (row, when, guests) => row.customer_name + ' declined the ' + row.title + ' appointment on ' + when + guests + '. Their contact card follows so you can call.',
	ownerFailed: (row, when) => 'The reminder for ' + row.customer_name + ', ' + row.title + ', ' + when + ' could not be delivered: ' + plain(row.last_error) + '. Check the number ' + row.phone + ', then set the row status back to scheduled.',
};
const hash = (text) => { let h = 5381; for (const c of text) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(16); };
const out = [];
for (const row of $input.all().map((item) => item.json).filter((r) => r.id !== undefined)) {
	const name = String(row.customer_name).trim().split(/\s+/)[0];
	const when = DateTime.fromISO(row.start_at).setZone($now.zoneName).toFormat(String(s.date_format || "cccc d LLLL 'at' HH:mm"));
	const extra = Number(row.extra_guests) > 0 ? Number(row.extra_guests) : 0;
	if (row.status === 'send_failed') {
		out.push({ json: { phone: s.owner_phone, text: wording.ownerFailed(row, when), key: 'failed-' + row.id + '-' + hash(String(row.last_error)) } });
		continue;
	}
	if (row.status === 'declined') {
		out.push({ json: {
			phone: s.owner_phone,
			text: wording.ownerDeclined(row, when, extra ? ' (+' + extra + ' guest(s))' : ''),
			key: 'decline-' + row.id + '-' + row.rsvp_at,
			card: true, card_name: row.customer_name, card_phone: row.phone, card_key: 'decline-card-' + row.id + '-' + row.rsvp_at,
		} });
	}
	const guests = extra ? ' We noted ' + extra + ' extra guest(s).' : '';
	out.push({ json: { phone: row.phone, text: fill(customerText[row.status], { name, title: row.title, business: s.business_name, when, guests }), key: 'rsvp-' + row.id + '-' + row.rsvp_at } });
}
return out;
